# Expected values generated by test/pandas/gen_expected.py (pandas 3.1.1).

import numpy as np
import pandas as pd
import hashlib

def make_F(n: int, m: int, seed: int = 12345):
    F = np.empty((n, m))
    s = seed
    for i in range(n):
        for j in range(m):
            s = (s * 1103515245 + 12345) % 2147483648
            F[i, j] = float(s % 20001 - 10000) * 0.000123 * float(j + 1)
    return F

def make_y(n: int):
    return np.array([(i * 7 % 5) % 2 for i in range(n)])

def _r(x) -> str:
    if isinstance(x, pd.Scalar):
        return repr(x.f) if x.kind == 0 else (repr(x.s) if x.kind == 3 else str(x))
    elif isinstance(x, float) or isinstance(x, str):
        return repr(x)
    else:
        return str(x)

@test
def test_repr():
    F = make_F(40, 8)
    y = make_y(40)
    df = pd.DataFrame(F, columns=[f"ch{i}" for i in range(F.shape[1])])
    df["label"] = y
    g = df.groupby("label").mean()
    d = df.drop(columns="label").describe()
    c = df.drop(columns="label").corr()
    csv = df.to_csv(float_format="%.17g")

    F2 = make_F(13, 4, seed=777)
    F2[3, 1] = float("nan")
    F2[7, 2] = float("nan")
    d2 = pd.DataFrame(F2, columns=["a", "b", "c", "d"])
    d2["k"] = np.array([i % 3 for i in range(13)], dtype=int)

    s3 = pd.DataFrame({"name": pd.Series(["b", "a", "c", "a", "b", "b"]), "v": pd.Series([1, 2, 3, 4, 5, 6]), "w": pd.Series([0.5, 1.5, 2.5, 3.5, 4.5, 5.5])})

    r = pd.DataFrame(make_F(25, 3, seed=99), columns=["x", "y", "z"])

    f = pd.DataFrame({"a": pd.Series([3, 1, 2, 5, 4]), "b": pd.Series([0.5, 2.25, -1.0, 3.5, 0.0]), "s": pd.Series(["x", "y,z", "w", 'q"t', "x"])})
    left = pd.DataFrame({"key": pd.Series([1, 2, 3, 4]), "lv": pd.Series([0.1, 0.2, 0.3, 0.4])})
    right = pd.DataFrame({"key": pd.Series([2, 4, 4, 5]), "rv": pd.Series(["p", "q", "r", "s"])})
    fn = pd.DataFrame({"v": pd.Series([1.0, float("nan"), 3.0]), "s": pd.Series([pd.Scalar.of("a"), pd.Scalar.of(None), pd.Scalar.of("c")])})
    sa = pd.Series([1.0, 2.0, 3.0], index=["a", "b", "c"])
    sb = pd.Series([10.0, 20.0, 30.0], index=["b", "c", "d"])

    txt = "id,name,score,flag\n1,ann,1.5,True\n2,bob,,False\n3,\"c,d\",3.25,True\n"
    rd = pd.read_csv_string(txt)
    rd2 = pd.read_csv_string(txt, index_col=0)
    rd3 = pd.read_csv_string(df.to_csv(), index_col=0)

    assert repr(df.head(3)) == '        ch0       ch1       ch2  ...       ch6       ch7  label\n0 -0.951651  0.257808  1.643895  ...  3.879666  2.038848      0\n1 -1.137504 -0.001968 -3.098862  ... -3.320016 -7.355400      0\n2 -0.382530  1.151526  1.073421  ...  0.342678  2.739456      0\n\n[3 rows x 9 columns]'
    assert repr(g) == '            ch0       ch1       ch2  ...       ch5       ch6       ch7\nlabel                                ...                              \n0      0.048908  0.433493  0.175690  ...  0.611648  0.690809 -2.527445\n1      0.288473 -0.092988 -0.839959  ...  0.863737 -0.758057  0.102090\n\n[2 rows x 8 columns]'
    assert repr(d) == '             ch0        ch1        ch2  ...        ch5        ch6        ch7\ncount  40.000000  40.000000  40.000000  ...  40.000000  40.000000  40.000000\nmean    0.144734   0.222901  -0.230570  ...   0.712484   0.111263  -1.475631\nstd     0.700270   1.484374   2.191785  ...   3.765828   5.311747   4.888391\nmin    -1.206015  -2.394318  -3.536865  ...  -6.756390  -8.216523  -9.296832\n25%    -0.384990  -1.241316  -2.048042  ...  -2.717501  -5.182144  -5.302776\n50%     0.196062   0.328287  -0.670104  ...   0.638370  -0.082226  -1.061736\n75%     0.796856   1.481597   1.672216  ...   4.152541   4.960221   2.637612\nmax     1.213026   2.363814   3.586311  ...   6.845688   8.371503   9.413928\n\n[8 rows x 8 columns]'
    assert repr(f) == '   a     b    s\n0  3  0.50    x\n1  1  2.25  y,z\n2  2 -1.00    w\n3  5  3.50  q"t\n4  4  0.00    x'
    assert repr(f["b"]) == '0    0.50\n1    2.25\n2   -1.00\n3    3.50\n4    0.00\nName: b, dtype: float64'
    assert repr(f["a"]) == '0    3\n1    1\n2    2\n3    5\n4    4\nName: a, dtype: int64'
    assert repr(f["s"]) == '0      x\n1    y,z\n2      w\n3    q"t\n4      x\nName: s, dtype: str'
    assert repr(fn) == '     v    s\n0  1.0    a\n1  NaN  NaN\n2  3.0    c'
    assert repr(pd.DataFrame({"x": pd.Series([1e7, 2.5]), "y": pd.Series([1e-8, 3.0])})) == '            x             y\n0  10000000.0  1.000000e-08\n1         2.5  3.000000e+00'
    assert repr(s3["name"].value_counts()) == 'name\nb    3\na    2\nc    1\nName: count, dtype: int64'
    print("test_repr: ok")

test_repr()
